    elif obfuscation_type == 'hex':
        return re.sub(r"'", r"'", payload.encode().hex())

    elif obfuscation_type == 'unicode':
        return re.sub(r"'", r"'", payload.encode().decode('unicode-escape'))

    elif obfuscation_type == 'javascript':
        return re.sub(r"'", r"'", payload.encode().decode('string-escape'))

